    vals_ev vals 70 = Z_to_bv 64 LEN -> vals_ev vals 71 = Z_to_bv 64 B0 -> vals_ev vals 72 = Z_to_bv 64 B1 ->
    Z.ltb LEN (CFG + 6) = t ->
    sc_denot RSEGS M (ENVb vals) (SCBr t BC_LTU (EVar 70) (EAlu ALU_ADD cfglen_x (ELit 6))).
Proof.
